#include <algorithm>
#include <string>
#include <utility>
#include <vector>

struct Item
{
    int weight;
    int value;
};

std::pair<int, std::vector<int>> knapsack(const std::vector<Item>& items, int capacity)
{
    std::size_t n = items.size();
    std::vector<std::vector<int>> t(n + 1, std::vector<int>(capacity + 1, 0));
    for (std::size_t i = 1; i <= n; ++i)
        for (int w = 0; w <= capacity; ++w)
        {
            t[i][w] = t[i - 1][w];
            if (items[i - 1].weight <= w) t[i][w] = std::max(t[i][w], t[i - 1][w - items[i - 1].weight] + items[i - 1].value);
        }
    std::vector<int> chosen;
    for (std::size_t i = n, w = static_cast<std::size_t>(capacity); i > 0; --i)
        if (t[i][w] != t[i - 1][w])
        {
            chosen.push_back(static_cast<int>(i - 1));
            w -= static_cast<std::size_t>(items[i - 1].weight);
        }
    std::reverse(chosen.begin(), chosen.end());
    return { t[n][capacity], chosen };
}

std::string lcs(const std::string& a, const std::string& b)
{
    std::vector<std::vector<int>> L(a.size() + 1, std::vector<int>(b.size() + 1, 0));
    for (std::size_t i = 1; i <= a.size(); ++i)
        for (std::size_t j = 1; j <= b.size(); ++j)
            L[i][j] = a[i - 1] == b[j - 1] ? L[i - 1][j - 1] + 1 : std::max(L[i - 1][j], L[i][j - 1]);
    std::string out;
    for (std::size_t i = a.size(), j = b.size(); i > 0 && j > 0;)
    {
        if (a[i - 1] == b[j - 1]) { out += a[i - 1]; --i; --j; }
        else if (L[i - 1][j] >= L[i][j - 1]) --i;
        else --j;
    }
    std::reverse(out.begin(), out.end());
    return out;
}

int editDistance(const std::string& a, const std::string& b)
{
    std::vector<int> prev(b.size() + 1), cur(b.size() + 1);
    for (std::size_t j = 0; j <= b.size(); ++j) prev[j] = static_cast<int>(j);
    for (std::size_t i = 1; i <= a.size(); ++i)
    {
        cur[0] = static_cast<int>(i);
        for (std::size_t j = 1; j <= b.size(); ++j)
            cur[j] = std::min({ prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] == b[j - 1] ? 0 : 1) });
        std::swap(prev, cur);
    }
    return prev[b.size()];
}

int lisLength(const std::vector<int>& values)
{
    std::vector<int> tails;
    for (int x : values)
    {
        auto it = std::lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x); else *it = x;
    }
    return static_cast<int>(tails.size());
}

std::vector<int> lis(const std::vector<int>& values)
{
    std::vector<int> tailValue, tailIndex, parent(values.size(), -1);
    for (std::size_t i = 0; i < values.size(); ++i)
    {
        std::size_t k = static_cast<std::size_t>(std::lower_bound(tailValue.begin(), tailValue.end(), values[i]) - tailValue.begin());
        if (k > 0) parent[i] = tailIndex[k - 1];
        if (k == tailValue.size()) { tailValue.push_back(values[i]); tailIndex.push_back(static_cast<int>(i)); }
        else { tailValue[k] = values[i]; tailIndex[k] = static_cast<int>(i); }
    }
    std::vector<int> out;
    for (int i = tailIndex.empty() ? -1 : tailIndex.back(); i != -1; i = parent[i]) out.push_back(values[i]);
    std::reverse(out.begin(), out.end());
    return out;
}

