#include <random>

static bool isSubsequence(const std::string& s, const std::string& of) { std::size_t j = 0; for (char c : of) if (j < s.size() && s[j] == c) ++j; return j == s.size(); }
static bool increasingSubsequence(const std::vector<int>& s, const std::vector<int>& of)
{
    for (std::size_t i = 1; i < s.size(); ++i) if (!(s[i - 1] < s[i])) return false;
    std::size_t j = 0;
    for (int x : of) if (j < s.size() && s[j] == x) ++j;
    return j == s.size();
}

TEST("knapsack") {
    std::vector<Item> items{ { 1, 1 }, { 3, 4 }, { 4, 5 }, { 5, 7 } };
    auto [value, chosen] = knapsack(items, 7);
    CHECK_EQ(value, 9);
    int w = 0, v = 0;
    for (int i : chosen) { w += items[i].weight; v += items[i].value; }
    CHECK(w <= 7);
    CHECK_EQ(v, 9);
    CHECK_EQ(knapsack(items, 0).first, 0);
    CHECK_EQ(knapsack({ { 10, 100 } }, 9).first, 0);
    std::vector<Item> many;
    for (int i = 1; i <= 100; ++i) many.push_back({ i, i * i % 97 + 1 });
    auto [best, picks] = knapsack(many, 1000);
    int tw = 0, tv = 0;
    for (int i : picks) { tw += many[i].weight; tv += many[i].value; }
    CHECK(tw <= 1000);
    CHECK_EQ(tv, best);
    CHECK_EQ(best, 2453);
}
TEST("longest common subsequence") {
    std::string s = lcs("AGGTAB", "GXTXAYB");
    CHECK_EQ(s.size(), std::size_t{ 4 });
    CHECK(isSubsequence(s, "AGGTAB") && isSubsequence(s, "GXTXAYB"));
    CHECK_EQ(lcs("abc", "xyz"), std::string(""));
    CHECK_EQ(lcs("", "abc"), std::string(""));
    std::string t = lcs("dynamic programming", "dramatic programs");
    CHECK_EQ(t.size(), std::size_t{ 13 });
    CHECK(isSubsequence(t, "dynamic programming") && isSubsequence(t, "dramatic programs"));
}
TEST("edit distance") {
    CHECK_EQ(editDistance("kitten", "sitting"), 3);
    CHECK_EQ(editDistance("flaw", "lawn"), 2);
    CHECK_EQ(editDistance("", "abc"), 3);
    CHECK_EQ(editDistance("same", "same"), 0);
    CHECK_EQ(editDistance("intention", "execution"), 5);
    std::string a(5000, 'a'), b(5000, 'a');
    for (int i = 0; i < 5000; i += 10) b[i] = 'b';
    CHECK_EQ(editDistance(a, b), 500);
    CHECK_EQ(editDistance(a, a.substr(100)), 100);
}
TEST("longest increasing subsequence") {
    CHECK_EQ(lisLength({ 3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5 }), 4);
    CHECK_EQ(lisLength({ 10, 9, 8 }), 1);
    CHECK_EQ(lisLength({}), 0);
    CHECK_EQ(lisLength({ 2, 2, 2 }), 1);
    std::vector<int> v{ 3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5 };
    auto s = lis(v);
    CHECK_EQ(s.size(), std::size_t{ 4 });
    CHECK(increasingSubsequence(s, v));
    CHECK(lis({}).empty());
}
TEST("200,000 values") {
    std::vector<int> v(200000);
    std::mt19937 rng(6);
    for (int i = 0; i < 200000; ++i) v[i] = i % 2 == 0 ? i : static_cast<int>(rng() % 1000);
    int n = lisLength(v);
    CHECK(n >= 99000);
    auto s = lis(v);
    CHECK_EQ(static_cast<int>(s.size()), n);
    CHECK(increasingSubsequence(s, v));
}

